mapper.select:
SELECT 
FROM lesson
WHERE YEAR(lesson_date) = #{year}
  AND MONTH(lesson_date) = #{month}
ORDER BY lesson_date, slot_id

SELECT COALESCE(SUM(c.price), 0)
FROM lesson l
JOIN course c ON l.course_id = c.id
WHERE YEAR(l.lesson_date) = #{year}
  AND MONTH(l.lesson_date) = #{month}
  AND l.status IN ('NORMAL', 'MADEUP')
